def articulationPoints(V, adj):
    def dfs(u, parent):
        nonlocal time
        low[u] = disc[u] = time
        time += 1
        children = 0
        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if parent != -1 and low[v] >= disc[u]:
                    ap[u] = True
            elif v != parent:
                low[u] = min(low[u], disc[v])
        if parent == -1 and children > 1:
            ap[u] = True

    disc = [-1] * V
    low = [-1] * V
    ap = [False] * V
    time = 0

    for i in range(V):
        if disc[i] == -1:
            dfs(i, -1)

    result = [i for i in range(V) if ap[i]]
    return result if result else [-1]

# Example usage:
# V = 5
# adj = [[1, 2], [0, 2], [0, 1, 3], [2, 4], [3]]
